// Превращает строки листа Settings (key/value) в объект и прокидывает дальше.
const rows = $input.all().map(i => i.json);
const settings = {};
for (const r of rows) {
  const key = (r.key ?? r.Key ?? '').toString().trim();
  if (!key) continue;
  settings[key] = (r.value ?? r.Value ?? '').toString().trim();
}
function bool(v, def) {
  if (v === undefined || v === '') return def;
  return String(v).toLowerCase() === 'true' || v === '1';
}
function num(v, def) {
  const n = Number(v);
  return Number.isFinite(n) ? n : def;
}
const cfg = {
  owner_chat_id: settings.owner_chat_id || '<REDACTED_CHAT_ID>',
  manager_chat_id: settings.manager_chat_id || '',
  allowed_chat_ids: (settings.allowed_chat_ids || settings.owner_chat_id || '<REDACTED_CHAT_ID>'),
  sla_hot_hours: num(settings.sla_hot_hours, 4),
  sla_warm_hours: num(settings.sla_warm_hours, 24),
  sla_repeat_hours: num(settings.sla_repeat_hours, 6),
  default_responsible: settings.default_responsible || 'Геннадий',
  ai_model: settings.ai_model || 'gpt-4.1-mini',
  ai_enabled_for_hot: bool(settings.ai_enabled_for_hot, true),
  ai_enabled_for_warm: bool(settings.ai_enabled_for_warm, true),
  ai_enabled_for_cold: bool(settings.ai_enabled_for_cold, false),
  auto_reply_enabled: bool(settings.auto_reply_enabled, false),
  auto_reply_default_lang: (settings.auto_reply_default_lang || 'ru').toLowerCase(),
  follow_up_enabled: bool(settings.follow_up_enabled, false),
  followup_hot_hours: num(settings.followup_hot_hours, 24),
  followup_warm_hours: num(settings.followup_warm_hours, 72),
  timezone: settings.timezone || 'Europe/Chisinau',
  currency: settings.currency || 'EUR'
};
return [{ json: { settings: cfg } }];

// Build Daily Digest — управленческий digest по лидам (plain text).
const cfg = (function(){ try { return $('Settings to Object').first().json.settings || {}; } catch(e){ return {}; } })();
const TZ = cfg.timezone || 'Europe/Chisinau';
const now = new Date();

const pipe = $('Get Pipeline Rows').all().map(i => i.json)
  .filter(r => r && Object.keys(r).length > 0 && (r.lead_id || r.company || r.name || r.email || r.phone || r.telegram));
let aiPlans = [];
try { aiPlans = $('Get AI Plans').all().map(i => i.json).filter(r => r && r.lead_id); } catch(e){ aiPlans = []; }

function val(r, ...keys){ for(const k of keys){ if(r[k]!==undefined&&r[k]!==null&&String(r[k]).trim()!=='') return String(r[k]).trim(); } return ''; }
function dkey(v){ if(!v) return ''; const d=new Date(v); return Number.isNaN(d.getTime())?'':d.toLocaleDateString('en-CA',{timeZone:TZ}); }
const today = now.toLocaleDateString('en-CA',{timeZone:TZ});
function isClosed(stage){ const s=String(stage).toLowerCase(); return ['won','lost','closed','nurture','закрыт'].some(x=>s.includes(x)); }
function hasContact(r){ return !!(val(r,'email')||val(r,'phone')||val(r,'telegram')); }
function isSnoozedFuture(r){ if(val(r,'sla_status').toLowerCase()!=='snoozed') return false; const u=new Date(val(r,'sla_snooze_until')); return !Number.isNaN(u.getTime())&&u>now; }
function isSnoozedExpired(r){ if(val(r,'sla_status').toLowerCase()!=='snoozed') return false; const u=new Date(val(r,'sla_snooze_until')); return !Number.isNaN(u.getTime())&&u<now; }
function isOverdue(r){
  const f=val(r,'next_follow_up_at'); if(!f) return false;
  const d=new Date(f); if(Number.isNaN(d.getTime())||d>=now) return false;
  const sla=val(r,'sla_status').toLowerCase();
  if(sla==='done'||sla==='nurture') return false;
  if(isClosed(val(r,'deal_stage'))) return false;
  if(isSnoozedFuture(r)) return false;
  return true;
}

const active = pipe.filter(r => !isClosed(val(r,'deal_stage')));
const byP = p => active.filter(r => val(r,'priority').toUpperCase()===p).length;
const newToday = pipe.filter(r => dkey(val(r,'created_at'))===today);
const redOrange = active.filter(r => ['RED','ORANGE'].includes(val(r,'financial_zone').toUpperCase()));
const overdue = pipe.filter(isOverdue);
const noNextAction = active.filter(r => !val(r,'next_action'));
const noContact = active.filter(r => !hasContact(r));
const snoozedExpired = pipe.filter(isSnoozedExpired);
const aiMissing = active.filter(r => {
  const p=val(r,'priority').toUpperCase(); if(p!=='HOT'&&p!=='WARM') return false;
  if(val(r,'ai_plan_ready').toUpperCase()==='Y') return false;
  const st=val(r,'deal_stage').toLowerCase();
  if(['won','lost','closed','nurture','incomplete'].some(x=>st.includes(x))) return false;
  return true;
});
const aiReady = active.filter(r => val(r,'ai_plan_ready').toUpperCase()==='Y').length;
const recentPlansToday = aiPlans.filter(r => dkey(val(r,'ai_created_at'))===today).length;

// ranking for top active leads
const zoneRank = z => ({RED:0,ORANGE:1,YELLOW:2,GREEN:3}[String(z).toUpperCase()] ?? 4);
const prioRank = p => ({HOT:0,WARM:1,COLD:2,INCOMPLETE:3}[String(p).toUpperCase()] ?? 4);
const topActive = active.slice().sort((a,b)=>{
  const ao=isOverdue(a)?0:1, bo=isOverdue(b)?0:1;
  return prioRank(val(a,'priority'))-prioRank(val(b,'priority'))
    || zoneRank(val(a,'financial_zone'))-zoneRank(val(b,'financial_zone'))
    || ao-bo;
}).filter(r => ['HOT','WARM'].includes(val(r,'priority').toUpperCase())).slice(0,10);

function leadLine(r,i){ return `${i}. ${val(r,'company')||'-'} / ${val(r,'name')||'-'} | ${val(r,'priority')||'-'}/${val(r,'financial_zone')||'-'} | ${val(r,'deal_stage')||'New'} | ${val(r,'next_action')||'-'} | ${val(r,'lead_id')}`; }
function overdueLine(r,i){ return `${i}. ${val(r,'company')||'-'} / ${val(r,'name')||'-'} | Due: ${dkey(val(r,'next_follow_up_at'))||val(r,'next_follow_up_at')} | ${val(r,'next_action')||'-'} | ${val(r,'lead_id')}`; }

// source/utm today
const srcMap = {};
for(const r of newToday){ const s=val(r,'utm_source')||'direct/unknown'; srcMap[s]=(srcMap[s]||0)+1; }
const srcLines = Object.keys(srcMap).length ? Object.entries(srcMap).map(([k,v])=>`${k}: ${v}`).join('\n') : 'No new leads today';

const stats = { active: active.length, new_today: newToday.length, hot: byP('HOT'), warm: byP('WARM'),
  cold: byP('COLD'), incomplete: byP('INCOMPLETE'), overdue: overdue.length };

let msg;
if (active.length === 0) {
  msg = `FINMENTOR Daily Lead Digest\nDate: ${today}\nNo new or active lead issues today.\nPipeline is clean.`;
} else {
  msg =
`FINMENTOR Daily Lead Digest
Date: ${today}
Timezone: ${TZ}

1. Summary
Total active leads: ${active.length}
New today: ${newToday.length}
HOT: ${byP('HOT')}
WARM: ${byP('WARM')}
COLD: ${byP('COLD')}
INCOMPLETE: ${byP('INCOMPLETE')}
RED/ORANGE: ${redOrange.length}

2. Attention today
Overdue follow-ups: ${overdue.length}
No next action: ${noNextAction.length}
No contact: ${noContact.length}
AI plan not ready: ${aiMissing.length}
Snoozed expired: ${snoozedExpired.length}

3. HOT / RED active leads
${topActive.length ? topActive.map((r,i)=>leadLine(r,i+1)).join('\n') : '-'}

4. Follow-up overdue
${overdue.length ? overdue.slice(0,10).map((r,i)=>overdueLine(r,i+1)).join('\n') : '-'}

5. AI status
AI ready: ${aiReady}
AI missing: ${aiMissing.length}
Recent X-Ray plans today: ${recentPlansToday}

6. Source / UTM today
${srcLines}

7. Recommended owner actions
- Contact HOT overdue leads today.
- Review RED/ORANGE leads.
- Schedule Discovery for qualified leads.
- Move stale leads to Nurture if no response.`;
}

if (msg.length > 3800) msg = msg.slice(0,3800) + '\n...\nFull list in Google Sheets.';

return [{ json: { digest_message: msg, stats } }];

// Digest Activity — читает статистику из Build Daily Digest (Telegram отдаёт свой ответ).
const s = (function(){ try { return $('Build Daily Digest').first().json.stats || {}; } catch(e){ return {}; } })();
return [{ json: {
  activity_id: 'daily-digest-' + Date.now(),
  ts: new Date().toISOString(),
  lead_id: 'DAILY',
  actor: 'system:digest',
  channel: 'telegram',
  action: 'daily_digest_sent',
  detail: `Daily digest sent: active=${s.active||0}; new_today=${s.new_today||0}; overdue=${s.overdue||0}; hot=${s.hot||0}; warm=${s.warm||0}`
}}];
